SELECT id, uid, title, created_at, updated_at, last_active_tuid, last_active_tid, turn_seq
FROM sessions
WHERE id = #{id,typeHandler=org.apache.ibatis.type.ByteArrayTypeHandler}

SELECT id, uid, title, created_at, updated_at, last_active_tuid, last_active_tid, turn_seq
FROM sessions
WHERE uid = #{uid}

    AND title LIKE CONCAT('%', #{title}, '%')

ORDER BY updated_at DESC
LIMIT #{offset}, #{limit}

mapper.update:
UPDATE sessions
uid = #{uid}, title = #{title}, created_at = #{createdAt}, updated_at = #{updatedAt}, last_active_tuid = #{lastActiveTuid}, last_active_tid = #{lastActiveTid}, turn_seq = #{turnSeq},
WHERE id = #{id}
